  /// endpoint id, the only one history transfer dials.
  final String leafId;
  final String name;
  final String platform;
  final Uint8List endpointId;

  /// The digits the new device shows beside its code: for a pasted code,
  /// the person checks they match before adding it.
  final String comparison;

  const DmHandoffSealed({
    required this.sealed,
    required this.leafSignatureKey,
    required this.leafId,
    required this.name,
    required this.platform,
    required this.endpointId,
    required this.comparison,
  });

  @override
  int get hashCode =>
      sealed.hashCode ^
      leafSignatureKey.hashCode ^
      leafId.hashCode ^
      name.hashCode ^
      platform.hashCode ^
      endpointId.hashCode ^
      comparison.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is DmHandoffSealed &&
          runtimeType == other.runtimeType &&
          sealed == other.sealed &&
          leafSignatureKey == other.leafSignatureKey &&
          leafId == other.leafId &&
          name == other.name &&
          platform == other.platform &&
          endpointId == other.endpointId &&
          comparison == other.comparison;
}

/// A conversation the other person isn't in yet (row 676): none of their
/// devices passes the checks there, so nothing is sent until one does.
